#!/usr/bin/env bash
# Fully expanded production runner for Experiment 1 EX, p122k, total 1M, A/B=85/15.
# Run from the repository root after activating the SerialFlavour/GN2 environment.
# To run another EX1 point, copy this file and replace every config/output path.

set -euo pipefail

mkdir -p logs/parallel_refine/experiment1_ex_p122k_n1m_a095_b005/plain

echo "STAGE 1: prepare 70/10/20 A/B/Y processed caches"
