echo "STAGE 2: train five Parallel models"
CUDA_VISIBLE_DEVICES=0 python scripts/train_parallel.py --config configs/parallel_refine/experiments/experiment1_ex/experiment1_ex_p122k_n1m_a095_b005.json --seed 1 --skip-complete >logs/parallel_refine/experiment1_ex_p122k_n1m_a095_b005/plain/parallel_seed1_gpu0.log 2>&1 &
