CUDA_VISIBLE_DEVICES=2 python scripts/train_parallel.py --config configs/parallel_refine/experiments/experiment1_ex/experiment1_ex_p122k_n1m_a095_b005.json --seed 5 --skip-complete >logs/parallel_refine/experiment1_ex_p122k_n1m_a095_b005/plain/parallel_seed5_gpu2.log 2>&1 &
wait

echo "STAGE 3: generate B-train/B-val frozen feature and graph caches"
CUDA_VISIBLE_DEVICES=0 python scripts/generate_cache.py --config configs/parallel_refine/experiments/experiment1_ex/experiment1_ex_p122k_n1m_a095_b005.json --seed 1 --split b_train --split b_val >logs/parallel_refine/experiment1_ex_p122k_n1m_a095_b005/plain/b_cache_seed1_gpu0.log 2>&1 &
